from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import combinations


def _routes(data, minimum_duration, exact):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit.get(source, 0)
    coupons = data["coupons"]
    start = data["start"]
    # State tracks used coupons and visited requirements as well as the node.
    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and (not exact or used == coupons):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_component_01():
    return lambda data: _routes(data, 1, False)


def _build_component_02():
    return lambda data: _routes(data, 1, True)


def _build_component_03():
    return lambda data: _routes(data, 2, False)


def _build_component_04():
    return lambda data: _routes(data, 2, True)


def _build_component_05():
    return lambda data: _routes(data, 1, False)


def _build_component_06():
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(numerator):
            if mode == "half_up":
                return (numerator + 5000) // 10000
            return numerator // 10000

        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            tax = rounded(net * event.get("tax_bp", 0))
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        constraints = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        best_vector = None
        best_chosen = None

        def visit(chosen, limits, edges):
            nonlocal best_vector, best_chosen
            pending = sorted(name for name in limits if name not in chosen)
            if not pending:
                # Reject cycles in the active dependency graph.
                done, active = set(), set()

                def acyclic(name):
                    if name in active:
                        return False
                    if name in done:
                        return True
                    active.add(name)
                    for child in edges.get(name, ()):
                        if not acyclic(child):
                            return False
                    active.remove(name)
                    done.add(name)
                    return True

                if not all(acyclic(name) for name in chosen):
                    return
                vector = tuple(chosen.get(name, -1) for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best_chosen = dict(chosen)
                return

            name = pending[0]
            low = max(rng[0] for rng in limits[name])
            high = min(rng[1] for rng in limits[name])
            forbidden = set(blocked.get(name, []))
            if name in pins:
                forbidden_versions = forbidden
                rows = [row for row in packages[name]
                        if row["version"] == pins[name] and row["version"] not in forbidden_versions
                        and low <= row["version"] <= high]
            else:
                rows = [row for row in packages[name]
                        if row["version"] not in forbidden and low <= row["version"] <= high]
            for row in rows:
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_limits = {key: list(value) for key, value in limits.items()}
                next_edges = {key: list(value) for key, value in edges.items()}
                active_deps = [dep for dep in row.get("deps", [])
                               if not dep.get("feature") or dep["feature"] in features]
                next_edges[name] = []
                valid = True
                for dep in active_deps:
                    child = dep["name"]
                    next_edges[name].append(child)
                    next_limits.setdefault(child, []).append((dep["min"], dep["max"]))
                    if child in next_chosen:
                        child_version = next_chosen[child]
                        if not all(lo <= child_version <= hi
                                   for lo, hi in next_limits[child]):
                            valid = False
                            break
                if valid:
                    visit(next_chosen, next_limits, next_edges)

        visit({}, constraints, {})
        if best_chosen is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_chosen}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        best_value = None
        best_ids = None
        for chosen in combinations(jobs, k):
            ids = [job["id"] for job in chosen]
            id_set = set(ids)
            if not mandatory.issubset(id_set):
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in data.get("quotas", {}).items()):
                continue
            intervals = sorted((job["start"], job["end"]) for job in chosen)
            if any(intervals[i][0] < intervals[i - 1][1]
                   for i in range(1, len(intervals))):
                continue
            value = sum(job["value"] for job in chosen)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and sorted_ids > best_ids)):
                best_value = value
                best_ids = sorted_ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
